getChatRoomFieldValuesFromString(aString) {
  const params = aString.trim().split(/\s+/);
  const chatFields = { channel: params[0] };
  if (params.length > 1) {
    chatFields.password = params[1];
  }
  return new ChatRoomFieldValues(chatFields);
},

